"""
Execution-grounded verification of agent-authored workspaces.

This module implements the ExecutionHarness which verifies code by actually
running it (parsing, installing, importing, testing) rather than relying on
textual analysis of prose.
"""

import ast
import os
import sys
import subprocess
import tempfile
import shutil
import time
import re
import json
import tomllib
from dataclasses import dataclass, field
from typing import Dict, List, Optional, Any, Tuple, Iterable

# Constants
SKIPPED = 'skipped'
PASSED = 'passed'
FAILED = 'failed'
DEFAULT_PENALTY_PER_GATE = 6.25
DEFAULT_TIMEOUT_S = 60

# Import artifacts module if available, otherwise define fallbacks
try:
    from hae.evaluation.artifacts import (
        is_generated_path,
        is_malformed_path,
        sanitize_path,
        filter_bundle,
        partition_bundle,
        count_source_files,
        EXCLUDED_DIR_SEGMENTS,
        EXCLUDED_DIR_SUFFIXES
    )
except ImportError:
    # Fallback definitions if artifacts.py is not yet available or import fails
    EXCLUDED_DIR_SEGMENTS = ('.pytest_cache', '__pycache__', 'venv', '.venv', '.git', '.mypy_cache', '.ruff_cache', '.tox', 'node_modules', '.ipynb_checkpoints')
    EXCLUDED_DIR_SUFFIXES = ('.egg-info', '.dist-info')

    def is_generated_path(path: str) -> bool:
        parts = path.replace('\\', '/').split('/')
        for part in parts:
            if part in EXCLUDED_DIR_SEGMENTS:
                return True
            if any(part.endswith(s) for s in EXCLUDED_DIR_SUFFIXES):
                return True
        return False

    def is_malformed_path(path: str) -> bool:
        if not path:
            return True
        if '*' in path or '`' in path:
            return True
        if path != path.strip():
            return True
        if path.startswith('-'):
            return True
        if path.endswith('.') or path.endswith('~'):
            return True
        return False

    def sanitize_path(path: str) -> str:
        path = path.strip()
        path = path.replace('*', '').replace('`', '')
        if path.startswith('-'):
            path = path[1:]
        if path.endswith('.') or path.endswith('~'):
            path = path[:-1]
        return path

    def filter_bundle(bundle: Dict[str, str]) -> Dict[str, str]:
        return {k: v for k, v in bundle.items() if not is_generated_path(k) and not is_malformed_path(k)}

    def partition_bundle(bundle: Dict[str, str]) -> Tuple[Dict[str, str], Dict[str, str], Dict[str, str]]:
        authored = {}
        generated = {}
        malformed = {}
        for k, v in bundle.items():
            if is_generated_path(k):
                generated[k] = v
            elif is_malformed_path(k):
                malformed[k] = v
            else:
                authored[k] = v
        return authored, generated, malformed

    def count_source_files(bundle: Dict[str, str], suffixes: Iterable[str] = ('.py',)) -> int:
        count = 0
        for path in bundle:
            if not is_generated_path(path) and not is_malformed_path(path):
                if any(path.endswith(s) for s in suffixes):
                    count += 1
        return count


@dataclass
class GateResult:
    """Outcome of a single verification gate."""
    name: str
    status: str
    method: str
    detail: str = ''
    duration_s: float = 0.0
    evidence: Dict[str, Any] = field(default_factory=dict)

    @property
    def passed(self) -> bool:
        return self.status == PASSED

    @property
    def evaluated(self) -> bool:
        return self.status != SKIPPED


@dataclass
class VerificationReport:
    """Aggregate result across all gates."""
    gates: List[GateResult]
    score_penalty: float
    authored_files: int
    python_files: int
    source: str = 'bundle'
    harness_version: str = '3.0-execution'

    def gate(self, name: str) -> Optional[GateResult]:
        for g in self.gates:
            if g.name == name:
                return g
        return None

    @property
    def evaluated_gates(self) -> List[GateResult]:
        return [g for g in self.gates if g.evaluated]

    @property
    def passed_gates(self) -> List[GateResult]:
        return [g for g in self.gates if g.passed]

    @property
    def gate_status(self) -> Dict[str, str]:
        """Gate name -> PASSED | FAILED | SKIPPED. The fitness function's input."""
        return {g.name: g.status for g in self.gates}

    @property
    def gate_detail(self) -> Dict[str, str]:
        return {g.name: g.detail for g in self.gates}

    @property
    def pass_rate(self) -> float:
        """Fraction of *evaluated* gates that passed. Skips are excluded."""
        evaluated = self.evaluated_gates
        if not evaluated:
            return 0.0
        passed = [g for g in evaluated if g.passed]
        return len(passed) / len(evaluated)

    def summary(self) -> str:
        lines = [f"Verification Report ({self.source})"]
        lines.append(f"Authored Files: {self.authored_files}, Python Files: {self.python_files}")
        lines.append(f"Score Penalty: {self.score_penalty:.2f}")
        lines.append("-" * 40)
        for g in self.gates:
            status_icon = "PASS" if g.passed else ("SKIP" if g.status == SKIPPED else "FAIL")
            lines.append(f"[{status_icon}] {g.name}: {g.detail}")
        lines.append("-" * 40)
        lines.append(f"Pass Rate (Evaluated): {self.pass_rate:.2%}")
        return "\n".join(lines)

    def to_dict(self) -> Dict[str, Any]:
        return {
            "gates": [
                {
                    "name": g.name,
                    "status": g.status,
                    "method": g.method,
                    "detail": g.detail,
                    "duration_s": g.duration_s,
                    "evidence": g.evidence
                }
                for g in self.gates
            ],
            "score_penalty": self.score_penalty,
            "authored_files": self.authored_files,
            "python_files": self.python_files,
            "source": self.source,
            "harness_version": self.harness_version,
            "pass_rate": self.pass_rate,
            "gate_status": self.gate_status
        }


def extract_code_blocks(text: str) -> Dict[str, str]:
    """Recovers a path->content map from fenced code blocks in a deliverable.

    A last resort, used only when a firm produced no live workspace. Only the
    contents of fenced blocks are returned; the surrounding prose is discarded
    and never reaches a gate.
    """
    if not text:
        return {}

    # Regex to find fenced code blocks with optional language and optional filename
    # Matches: ```python\n...``` or ```path/to/file.py\n...```
    # We look for blocks where the info string might contain a path ending in .py
    pattern = r"```(?:python|py)?\s*(.*?)\n(.*?)```"
    matches = re.findall(pattern, text, re.DOTALL)

    bundle = {}
    for info, content in matches:
        info = info.strip()
        # Try to extract a filename from the info string
        # Common patterns: "path/to/file.py", "file.py", "python path/to/file.py"
        filename = None
        if info:
            # Split by whitespace, look for something ending in .py
            parts = info.split()
            for part in parts:
                if part.endswith('.py'):
                    filename = part
                    break

        if filename:
            # Sanitize the filename if needed
            clean_filename = sanitize_path(filename)
            if clean_filename:
                bundle[clean_filename] = content

    return bundle


class ExecutionHarness:
    """Materializes a workspace bundle and verifies it by actually running it."""

    def __init__(self, timeout_s: int = DEFAULT_TIMEOUT_S, penalty_per_gate: float = DEFAULT_PENALTY_PER_GATE, python_executable: Optional[str] = None):
        self.timeout_s = timeout_s
        self.penalty_per_gate = penalty_per_gate
        self.python_executable = python_executable or sys.executable

    def verify_workspace(self, workspace: Any = None, deliverable_text: str = '') -> VerificationReport:
        """Verifies whatever code a firm actually produced.

        This is the entry point tournaments use. A firm normally writes into a
        live `AgentWorkspace`; if it never did, we fall back to the fenced code
        blocks embedded in its written deliverable.

        `deliverable_text` is *only* mined for code blocks. Its prose is never
        passed to a gate, because the entire point of this harness is that an
        essay about OpenTelemetry cannot satisfy the telemetry gate.
        """
        bundle = {}
        source = 'bundle'

        # Try to get bundle from workspace object
        if workspace is not None:
            # Check if workspace has a method to get files
            if hasattr(workspace, 'get_files'):
                bundle = workspace.get_files()
                source = 'workspace'
            elif hasattr(workspace, 'files'):
                bundle = workspace.files
                source = 'workspace'
            elif isinstance(workspace, dict):
                bundle = workspace
                source = 'workspace'

        # Fallback to deliverable text if bundle is empty
        if not bundle and deliverable_text:
            bundle = extract_code_blocks(deliverable_text)
            source = 'deliverable'

        return self.verify_bundle(bundle, source=source)

    def verify_bundle(self, bundle: Dict[str, str], source: str = 'bundle') -> VerificationReport:
        """Verifies an in-memory path->content map by writing it to a temp dir."""
        # Filter bundle to remove generated/malformed paths
        authored_bundle = filter_bundle(bundle)

        # Count files
        authored_files = len(authored_bundle)
        python_files = count_source_files(authored_bundle, suffixes=('.py',))

        # Create temp directory
        with tempfile.TemporaryDirectory() as tmpdir:
            # Write files to disk
            for path, content in authored_bundle.items():
                full_path = os.path.join(tmpdir, path)
                os.makedirs(os.path.dirname(full_path), exist_ok=True)
                with open(full_path, 'w', encoding='utf-8') as f:
                    f.write(content)

            # Run verification on the directory
            return self.verify_directory(tmpdir, authored=authored_bundle, source=source)

    def verify_directory(self, workdir: str, authored: Optional[Dict[str, str]] = None, source: str = 'directory') -> VerificationReport:
        """Verifies an existing workspace directory."""
        if authored is None:
            # Scan directory for files
            authored = {}
            for root, dirs, files in os.walk(workdir):
                # Prune excluded directories
                dirs[:] = [d for d in dirs if not is_generated_path(os.path.relpath(os.path.join(root, d), workdir))]

                for file in files:
                    rel_path = os.path.relpath(os.path.join(root, file), workdir)
                    if not is_generated_path(rel_path) and not is_malformed_path(rel_path):
                        full_path = os.path.join(root, file)
                        try:
                            with open(full_path, 'r', encoding='utf-8') as f:
                                authored[rel_path] = f.read()
                        except Exception:
                            pass

        authored_files = len(authored)
        python_files = count_source_files(authored, suffixes=('.py',))

        gates = []

        # Gate 1: Syntax
        gates.append(self._gate_syntax(workdir, authored))

        # Gate 2: Build
        gates.append(self._gate_build(workdir, authored))

        # Gate 3: Smoke
        gates.append(self._gate_smoke(workdir, authored))

        # Gate 4: Tests
        gates.append(self._gate_tests(workdir, authored))

        # Gate 5: Telemetry
        gates.append(self._gate_telemetry(workdir, authored))

        # Calculate penalty
        failed_count = sum(1 for g in gates if g.status == FAILED)
        score_penalty = failed_count * self.penalty_per_gate

        return VerificationReport(
            gates=gates,
            score_penalty=score_penalty,
            authored_files=authored_files,
            python_files=python_files,
            source=source
        )

    def _gate_syntax(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start_time = time.time()
        method = "ast.parse"

        py_files = {k: v for k, v in authored.items() if k.endswith('.py')}

        if not py_files:
            return GateResult(
                name="syntax",
                status=FAILED,
                method=method,
                detail="No Python files found.",
                duration_s=time.time() - start_time
            )

        errors = []
        for path, content in py_files.items():
            try:
                ast.parse(content)
            except SyntaxError as e:
                errors.append(f"{path}: {e}")

        duration = time.time() - start_time
        if errors:
            return GateResult(
                name="syntax",
                status=FAILED,
                method=method,
                detail="Syntax errors found: " + "; ".join(errors),
                duration_s=duration,
                evidence={"errors": errors}
            )

        return GateResult(
            name="syntax",
            status=PASSED,
            method=method,
            detail=f"All {len(py_files)} Python files parsed successfully.",
            duration_s=duration
        )

    def _gate_build(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start_time = time.time()
        method = "pip install -e ."

        # Check for packaging metadata
        has_pyproject = 'pyproject.toml' in authored
        has_setup_py = 'setup.py' in authored
        has_setup_cfg = 'setup.cfg' in authored

        if not (has_pyproject or has_setup_py or has_setup_cfg):
            return GateResult(
                name="build",
                status=FAILED,
                method=method,
                detail="No packaging metadata (pyproject.toml, setup.py, or setup.cfg) found.",
                duration_s=time.time() - start_time
            )

        # Validate pyproject.toml if present
        if has_pyproject:
            try:
                with open(os.path.join(workdir, 'pyproject.toml'), 'rb') as f:
                    data = tomllib.load(f)
                # Must contain at least one of [project], [build-system], or [tool]
                if not any(key in data for key in ['project', 'build-system', 'tool']):
                    return GateResult(
                        name="build",
                        status=FAILED,
                        method=method,
                        detail="pyproject.toml is valid TOML but missing required tables ([project], [build-system], or [tool]).",
                        duration_s=time.time() - start_time
                    )
            except Exception as e:
                return GateResult(
                    name="build",
                    status=FAILED,
                    method=method,
                    detail=f"pyproject.toml is invalid or unreadable: {e}",
                    duration_s=time.time() - start_time
                )

        # Attempt pip install
        try:
            # Check if pip is available
            subprocess.run([self.python_executable, '-m', 'pip', '--version'], 
                           capture_output=True, timeout=10, check=True)
        except Exception:
            return GateResult(
                name="build",
                status=SKIPPED,
                method=method,
                detail="pip not available or failed to run.",
                duration_s=time.time() - start_time
            )

        try:
            # Run pip install -e . --no-deps --no-build-isolation
            result = subprocess.run(
                [self.python_executable, '-m', 'pip', 'install', '-e', '.', '--no-deps', '--no-build-isolation'],
                cwd=workdir,
                capture_output=True,
                text=True,
                timeout=self.timeout_s
            )

            duration = time.time() - start_time

            if result.returncode == 0:
                return GateResult(
                    name="build",
                    status=PASSED,
                    method=method,
                    detail="Package installed successfully.",
                    duration_s=duration
                )
            else:
                return GateResult(
                    name="build",
                    status=FAILED,
                    method=method,
                    detail=f"pip install failed: {result.stderr}",
                    duration_s=duration,
                    evidence={"stderr": result.stderr, "stdout": result.stdout}
                )
        except subprocess.TimeoutExpired:
            return GateResult(
                name="build",
                status=FAILED,
                method=method,
                detail="pip install timed out.",
                duration_s=time.time() - start_time
            )
        except Exception as e:
            return GateResult(
                name="build",
                status=FAILED,
                method=method,
                detail=f"Error running pip install: {e}",
                duration_s=time.time() - start_time
            )

    def _gate_smoke(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start_time = time.time()
        method = "subprocess import"

        # Find non-test authored modules
        # Exclude test files
        module_files = []
        for path in authored:
            if not path.endswith('.py'):
                continue
            basename = os.path.basename(path).lower()
            if 'test' in basename:
                continue
            # Skip __init__.py as it's not a module to import directly in this context usually, 
            # but importing the package might trigger it. We'll try to import the file as a module.
            module_files.append(path)

        if not module_files:
            return GateResult(
                name="smoke",
                status=SKIPPED,
                method=method,
                detail="No importable non-test modules found.",
                duration_s=time.time() - start_time
            )

        # Prepare PYTHONPATH
        src_dir = os.path.join(workdir, 'src')
        env = os.environ.copy()
        current_pythonpath = env.get('PYTHONPATH', '')
        new_paths = [workdir, src_dir]
        if current_pythonpath:
            new_paths.append(current_pythonpath)
        env['PYTHONPATH'] = os.pathsep.join(new_paths)

        # Try to import each module
        import_errors = []
        module_not_found_errors = []

        for path in module_files:
            # Convert path to module name
            # e.g., src/foo/bar.py -> foo.bar
            # e.g., foo/bar.py -> foo.bar
            rel_path = path
            if rel_path.startswith('src/'):
                rel_path = rel_path[4:]

            module_name = rel_path.replace('/', '.').replace('\\', '.')
            if module_name.endswith('.py'):
                module_name = module_name[:-3]

            # Skip if it's just __init__
            if module_name.endswith('.__init__'):
                continue
            if module_name == '__init__':
                continue

            # Run subprocess to import
            code = f"import {module_name}"
            try:
                result = subprocess.run(
                    [self.python_executable, '-c', code],
                    cwd=workdir,
                    env=env,
                    capture_output=True,
                    text=True,
                    timeout=self.timeout_s
                )

                if result.returncode != 0:
                    stderr = result.stderr
                    if 'ModuleNotFoundError' in stderr:
                        # If a ModuleNotFoundError occurs during smoke import, it is treated as SKIPPED
                        # to allow the tests gate to run and correctly handle the dependency.
                        module_not_found_errors.append(f"{module_name}: {stderr}")
                    else:
                        import_errors.append(f"{module_name}: {stderr}")
            except Exception as e:
                import_errors.append(f"{module_name}: {e}")

        duration = time.time() - start_time

        if import_errors:
            return GateResult(
                name="smoke",
                status=FAILED,
                method=method,
                detail="Import errors: " + "; ".join(import_errors),
                duration_s=duration,
                evidence={"errors": import_errors}
            )

        if module_not_found_errors:
            return GateResult(
                name="smoke",
                status=SKIPPED,
                method=method,
                detail="Skipped due to missing third-party dependencies: " + "; ".join(module_not_found_errors),
                duration_s=duration,
                evidence={"skipped": module_not_found_errors}
            )

        return GateResult(
            name="smoke",
            status=PASSED,
            method=method,
            detail=f"All {len(module_files)} modules imported successfully.",
            duration_s=duration
        )

    def _gate_tests(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start_time = time.time()
        method = "pytest"

        # Find test files
        test_files = []
        for path in authored:
            if not path.endswith('.py'):
                continue
            basename = os.path.basename(path).lower()
            if 'test' in basename:
                test_files.append(path)

        if not test_files:
            return GateResult(
                name="tests",
                status=FAILED,
                method=method,
                detail="No test files found.",
                duration_s=time.time() - start_time
            )

        # Prepare PYTHONPATH
        src_dir = os.path.join(workdir, 'src')
        env = os.environ.copy()
        current_pythonpath = env.get('PYTHONPATH', '')
        new_paths = [workdir, src_dir]
        if current_pythonpath:
            new_paths.append(current_pythonpath)
        env['PYTHONPATH'] = os.pathsep.join(new_paths)

        # Check if pytest is installed
        try:
            subprocess.run([self.python_executable, '-m', 'pytest', '--version'], 
                           capture_output=True, timeout=10, check=True)
            has_pytest = True
        except Exception:
            has_pytest = False

        if has_pytest:
            method = "pytest"
            try:
                result = subprocess.run(
                    [self.python_executable, '-m', 'pytest', '-v'],
                    cwd=workdir,
                    env=env,
                    capture_output=True,
                    text=True,
                    timeout=self.timeout_s
                )
                duration = time.time() - start_time

                if result.returncode == 0:
                    return GateResult(
                        name="tests",
                        status=PASSED,
                        method=method,
                        detail="All tests passed.",
                        duration_s=duration
                    )
                else:
                    # Check if failure is due to ModuleNotFoundError
                    if 'ModuleNotFoundError' in result.stderr or 'ModuleNotFoundError' in result.stdout:
                        # Check if it's a test dependency or the code itself
                        # If the code itself fails to import, it's a failure.
                        # If a test dependency is missing, it's skipped.
                        # This is tricky. If pytest fails to collect tests due to import error, it's skipped.
                        # If tests run and fail, it's failed.
                        # If tests run and pass, it's passed.

                        # If pytest exits with non-zero, it could be collection error or test failure.
                        # If it's a collection error due to ModuleNotFoundError, we skip.
                        # If it's a test failure, we fail.

                        # Heuristic: If "ModuleNotFoundError" is in stderr, it's likely a collection/import issue.
                        # But if tests ran and failed, stderr might not have it.
                        # Let's assume if ModuleNotFoundError is present, it's a skip.
                        return GateResult(
                            name="tests",
                            status=SKIPPED,
                            method=method,
                            detail="Tests skipped due to missing dependencies.",
                            duration_s=duration,
                            evidence={"stderr": result.stderr}
                        )

                    return GateResult(
                        name="tests",
                        status=FAILED,
                        method=method,
                        detail="Tests failed.",
                        duration_s=duration,
                        evidence={"stdout": result.stdout, "stderr": result.stderr}
                    )
            except subprocess.TimeoutExpired:
                return GateResult(
                    name="tests",
                    status=FAILED,
                    method=method,
                    detail="Tests timed out.",
                    duration_s=time.time() - start_time
                )
            except Exception as e:
                return GateResult(
                    name="tests",
                    status=FAILED,
                    method=method,
                    detail=f"Error running pytest: {e}",
                    duration_s=time.time() - start_time
                )
        else:
            # Stdlib fallback
            method = "unittest fallback"
            # Run a script that imports test files and runs tests
            # We need to collect both bare test_* functions and unittest.TestCase subclasses

            test_script = """
import sys
import os
import unittest
import importlib
import traceback
import inspect
import tempfile

test_files = {test_files_repr}
results = []
errors = []
skipped = False

for tf in test_files:
    try:
        # Convert path to module name
        rel_path = tf
        if rel_path.startswith('src/'):
            rel_path = rel_path[4:]
        module_name = rel_path.replace('/', '.').replace(' ', '.')
        if module_name.endswith('.py'):
            module_name = module_name[:-3]

        mod = importlib.import_module(module_name)

        # Collect bare test_* functions
        for name in dir(mod):
            if name.startswith('test_'):
                func = getattr(mod, name)
                if callable(func):
                    # Check if it takes 0 required arguments
                    try:
                        sig = inspect.signature(func)
                        required_args = [p for p in sig.parameters.values() if p.default is inspect.Parameter.empty and p.kind not in (inspect.Parameter.VAR_POSITIONAL, inspect.Parameter.VAR_KEYWORD)]
                        if len(required_args) == 0:
                            try:
                                func()
                                results.append((tf, name, 'passed'))
                            except Exception as e:
                                errors.append((tf, name, str(e)))
                    except Exception:
                        pass

        # Collect unittest.TestCase subclasses
        for name in dir(mod):
            cls = getattr(mod, name)
            if isinstance(cls, type) and issubclass(cls, unittest.TestCase) and cls is not unittest.TestCase:
                suite = unittest.TestLoader().loadTestsFromTestCase(cls)
                runner = unittest.TextTestRunner(verbosity=0)
                res = runner.run(suite)
                if res.wasSuccessful():
                    results.append((tf, name, 'passed'))
                else:
                    errors.append((tf, name, 'unittest failure'))

    except ModuleNotFoundError as e:
        skipped = True
    except Exception as e:
        errors.append((tf, 'import', str(e)))

if skipped and not results and not errors:
    print("SKIPPED")
elif skipped and not results:
    print("SKIPPED")
elif errors:
    print("FAILED")
    for e in errors:
        print(e)
else:
    print("PASSED")
"""

            try:
                # We need to pass the test files to the script
                # Using a temporary script file might be safer than -c for complex code
                script_path = os.path.join(workdir, '_test_runner.py')
                with open(script_path, 'w') as f:
                    f.write(test_script.format(test_files_repr=repr(test_files)))

                result = subprocess.run(
                    [self.python_executable, script_path],
                    cwd=workdir,
                    env=env,
                    capture_output=True,
                    text=True,
                    timeout=self.timeout_s
                )

                duration = time.time() - start_time

                # Clean up script
                try:
                    os.remove(script_path)
                except:
                    pass

                output = result.stdout.strip()

                if output.startswith("PASSED"):
                    return GateResult(
                        name="tests",
                        status=PASSED,
                        method=method,
                        detail="All tests passed (stdlib fallback).",
                        duration_s=duration
                    )
                elif output.startswith("SKIPPED"):
                    return GateResult(
                        name="tests",
                        status=SKIPPED,
                        method=method,
                        detail="Tests skipped due to missing dependencies.",
                        duration_s=duration
                    )
                else:
                    return GateResult(
                        name="tests",
                        status=FAILED,
                        method=method,
                        detail="Tests failed (stdlib fallback).",
                        duration_s=duration,
                        evidence={"output": output, "stderr": result.stderr}
                    )
            except Exception as e:
                return GateResult(
                    name="tests",
                    status=FAILED,
                    method=method,
                    detail=f"Error running stdlib fallback: {e}",
                    duration_s=time.time() - start_time
                )

    def _gate_telemetry(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start_time = time.time()
        method = "ast analysis"

        py_files = {k: v for k, v in authored.items() if k.endswith('.py')}

        if not py_files:
            return GateResult(
                name="telemetry",
                status=FAILED,
                method=method,
                detail="No Python files found.",
                duration_s=time.time() - start_time
            )

        has_import = False
        has_call = False

        tracer_methods = {
            'start_as_current_span',
            'start_span',
            'get_tracer',
            'get_tracer_provider',
            'set_tracer_provider',
            'get_meter'
        }

        for path, content in py_files.items():
            try:
                tree = ast.parse(content)
            except SyntaxError:
                continue

            for node in ast.walk(tree):
                # Check for import opentelemetry or from opentelemetry ... import ...
                if isinstance(node, ast.Import):
                    for alias in node.names:
                        if alias.name == 'opentelemetry' or alias.name.startswith('opentelemetry.'):
                            has_import = True
                elif isinstance(node, ast.ImportFrom):
                    if node.module == 'opentelemetry' or (node.module and node.module.startswith('opentelemetry.')):
                        has_import = True

                # Check for calls to tracer/span methods
                if isinstance(node, ast.Call):
                    func = node.func
                    # Handle direct calls: get_tracer()
                    if isinstance(func, ast.Name):
                        if func.id in tracer_methods:
                            has_call = True
                    # Handle method calls: tracer.start_span()
                    elif isinstance(func, ast.Attribute):
                        if func.attr in tracer_methods:
                            has_call = True

        duration = time.time() - start_time

        if has_import and has_call:
            return GateResult(
                name="telemetry",
                status=PASSED,
                method=method,
                detail="OpenTelemetry import and tracer/span calls found.",
                duration_s=duration
            )
        else:
            detail = []
            if not has_import:
                detail.append("No OpenTelemetry import found.")
            if not has_call:
                detail.append("No tracer/span method calls found.")
            return GateResult(
                name="telemetry",
                status=FAILED,
                method=method,
                detail=" ".join(detail),
                duration_s=duration
            )
